{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 Bucket lacks a configured ACL",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The ACL is set to a variable 'var.bucket_acl' which could potentially be set to a public ACL, exposing the bucket to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "Lack of versioning means that if objects are accidentally deleted or overwritten, they cannot be recovered."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"bucket_2\" {\n  bucket = \"roger-bucket-2\"\n  acl    = \"private\"\n  versioning {\n    enabled = true\n  }\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        kms_master_key_id = aws_kms_key.my_key.arn\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n}",
  "fix_summary": "Set the ACL to 'private' to prevent potential public exposure and enabled versioning on the S3 bucket to allow for object recovery in case of accidental deletion or overwrite."
}
